def prima_anual(suma_asegurada, edad, fumador=False, tasa_base=0.0025):
    prima = suma_asegurada * tasa_base
    if edad >= 60:
        prima = prima * 1.50
    elif edad >= 40:
        prima = prima * 1.20
    if fumador:
        prima = prima * 1.35
    if suma_asegurada > 50_000_000:
        prima = prima * 0.95
    return round(prima, 2)
